package com.troday.api.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="reviews") public class Review { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="reviewer_id") private Long reviewerId; @Column(name="room_id") private Long roomId; @Column(name="contract_id") private Long contractId; @Column(name="room_tenant_id") private Long roomTenantId; private Integer rating; @Lob private String content; private String status="PUBLISHED"; @Column(name="hidden_by_id") private Long hiddenById; private String hiddenReason; private LocalDateTime hiddenAt; public Long getId(){return id;} public Long getReviewerId(){return reviewerId;} public void setReviewerId(Long v){reviewerId=v;} public Long getRoomId(){return roomId;} public void setRoomId(Long v){roomId=v;} public Long getContractId(){return contractId;} public void setContractId(Long v){contractId=v;} public Long getRoomTenantId(){return roomTenantId;} public void setRoomTenantId(Long v){roomTenantId=v;} public Integer getRating(){return rating;} public void setRating(Integer v){rating=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Long getHiddenById(){return hiddenById;} public void setHiddenById(Long v){hiddenById=v;} public String getHiddenReason(){return hiddenReason;} public void setHiddenReason(String v){hiddenReason=v;} public LocalDateTime getHiddenAt(){return hiddenAt;} public void setHiddenAt(LocalDateTime v){hiddenAt=v;} }
